#!/usr/bin/env python3
"""Production mesh loader, LOD, chain clipping and cache tests with Gson and API stand-ins.
Not a Minecraft/OpenGL runtime test. Full Forge compilation is a separate check.
"""
from pathlib import Path
import argparse,os,subprocess,tempfile
root=Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--gson',required=True);args=p.parse_args();gson=str(Path(args.gson).resolve())
