 for name,body in sources.items():f=dest/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(body)
 for name in['RiggingMeshes','TowerRiggingMath']:(dest/f'com/concertstage/client/{name}.java').write_text((root/f'common/src/main/java/com/concertstage/client/{name}.java').read_text())
 jdk=Path(os.environ['JAVA_HOME'])/'bin';subprocess.run([str(jdk/'javac'),'-cp',gson,'-d',str(dest),*[str(f)for f in dest.rglob('*.java')]],check=True);subprocess.run([str(jdk/'java'),'-Dassets='+str(root/'common/src/main/resources/assets/concertstage'),'-cp',str(dest)+os.pathsep+gson,'com.concertstage.client.RendererCheck'],check=True)
